"""Final scientific sections, based on saved numerical controls."""
import json
from pathlib import Path
import review11_sections as old
from prepare_source_v12 import renumber
BASE=Path(__file__).resolve().parent;ROOT=BASE.parent;AUD=ROOT/'revision_12_2026-10-23'
def read(n):return json.loads((AUD/n).read_text())
def add_section(doc,marker,paragraph,table,figure):
    if marker!='Q1_DISCRETIZATION_V12':
        def p(d,text,*args,**kwargs):return paragraph(d,renumber(text),*args,**kwargs)
        def f(d,path,caption,*args,**kwargs):
            if marker=='Q1_RESOLUTION':caption=caption.replace('Figure 8 ','Figure 10 ')
            return figure(d,path,renumber(caption),*args,**kwargs)
        return old.add_section(doc,marker,p,table,f)
    wave=read('waveform_mask_audit.json');wr=wave['waveforms'];m=wave['masks']
    ir=read('interface24_summary.json')['rows'];pr=read('physical_geometry_summary.json')['rows']
    sel=read('interface_phase_selection.json');psel=read('physical_phase_selection.json')
    paragraph(doc,'Full-waveform and mask controls distinguish stability of a response contrast from convergence of the observations themselves. On the same 102 phases, the combined-relief waveform changes by 0.1413 and 0.2179 µm RMS from h=0.50 mm to 0.35 and 0.25 mm, respectively, despite correlations exceeding 0.9998. The corresponding changes in the isolated dedendum waveform are only 0.00106 and 0.00114 µm RMS (Figure 8; Supplementary Table S17). Subtraction cancels much of the common elastic-discretization change. A stable differential signal can therefore coexist with a moving total waveform and a larger residual against an unchanged analytical operator. These comparisons diagnose the tested mesh sequence, not its asymptotic limit.')
    figure(doc,'fig_waveforms_v12.png','Figure 8 Mean-removed waveforms on the 102 common interior observations: combined-relief response, isolated dedendum contrast, change from the coarsest bulk mesh, and analytical inverse residual. Lines connect retained samples; unresolved transition values are not supplied.')
    paragraph(doc,'The phase mask excludes 18 of the original 120 stations where the nominal interior contact patch is clipped. Eroding the retained mask by one, two and three neighbouring stations around each excluded block leaves 98, 94 and 90 observations. Eight starts are used for both unrestricted and addendum-only fits on each mask. Residuals decrease from 0.2778 to 0.2524 µm with erosion, but unrestricted and restricted objectives remain equal within 1.1×10⁻⁷ in χ² (Supplementary Table S18). Failure to establish dedendum presence is therefore robust to these additional exclusions, within resolved interior data. At the generating truth, the analytical full-cycle smallest singular value, normalized to 120 observations, is 3.706 versus 0.981 on the original interior mask and 0.821 after three-station erosion. The omitted region is informative in the analytical model; it cannot be counted as observed FE information without resolving its contact geometry.')
    paragraph(doc,f"A separate interface control uses P2 elasticity at h=0.35 mm and pressure-hat spacings 0.04, 0.02 and 0.01 mm. The 71 geometric trace vertices, 0.02 mm local mesh target, normals and body meshes are fixed across pressure spacings; gaps are averaged with the consistent linear-hat mass matrix. Twenty-four common phases are selected uniformly from {sel['eligible_count']} of the 102 interior phases whose candidate traces lie above both root-blend boundaries. This eligibility rule is saved with the records. The test isolates interface spacing on that subset rather than replacing the original P1 inverse data.")
    paragraph(doc,'The isolated dedendum RMS values at successive interface spacings are '+', '.join(f"{r['isolated_dedendum_rms_um']:.6f}" for r in ir)+f" µm. The last refinement changes that RMS by {ir[-1]['isolated_signal_relative_change_percent']:+.3f}% and the combined waveform by {ir[-1]['combined_waveform_change_rms_um']:.6f} µm RMS (Supplementary Table S19). Identical body node counts are checked phase by phase. Three interface levels provide a sensitivity check; no asymptotic convergence order, full-cycle transition convergence or inverse-parameter convergence follows from them.")
    paragraph(doc,'A second P2 experiment physically removes material from the upper pinion flanks and their root blends. Quadratic relief with start s_d=0.25 and depths 10 and 50 µm displaces the polygonal contour inward. A harmonic boundary-fitted mesh deformation updates interior coordinates; elastic stiffness is reassembled and condensed anew for each depth. Bore constraints and wheel geometry are fixed, and addendum relief is absent in this controlled comparison. No extra contact gap is added. All candidate contacts lie above the modified region, so their locations, normals and pressure-load operator are unchanged by construction. Positive removed area, positive signed element-area ratios and compliance symmetry are verified. This isolates a structural effect excluded from the invariance proof.')
    paragraph(doc,f"Eight common phases are selected from {psel['eligible_count']} of the 102 interior phases for which every candidate pinion contact has ξ>0.251. The modified contour uses a 0.10 mm root-blend trim and twice the baseline contour-point density, with h=0.50, 0.35 and 0.25 mm. These settings differ from the P1 gap test and are not used to recalibrate it. The centred displacement difference is evaluated on the same eight phases at each mesh, not extrapolated to an entire cycle.")
    descriptions=[]
    last_changes=[]
    for depth in [.01,.05]:
        rr=[r for r in pr if r['depth_mm']==depth]
        descriptions.append(f"For {depth*1000:.0f} µm removal, the eight-phase centred response differences are "+', '.join(f"{r['centered_TE_difference_rms_um']:.6f}" for r in rr)+' µm RMS across the three bulk meshes.')
        last_changes.append(100*abs(rr[-1]['centered_TE_difference_rms_um']/rr[-2]['centered_TE_difference_rms_um']-1))
    paragraph(doc,' '.join(descriptions)+f" Last-refinement changes are below {max(last_changes):.2f}% for these contrasts. Nonzero compliance and displacement changes show that unloaded relief can influence transmission error through structural flexibility when fixed compliance is relaxed. They do not contradict conditional gap invariance. Their small magnitude in this test does not establish general physical invisibility, and the limited phase set does not validate physical profile recovery (Supplementary Table S20).")
    figure(doc,'fig_controls_v12.png','Figure 9 Dedicated P2 controls. Left: isolated dedendum contrast at three pressure-hat spacings on 24 common eligible phases and identical body meshes. Right: eight-phase centred approach change after physical 50 µm removal and elastic-stiffness reassembly at three bulk mesh sizes. Lines connect tested phases and do not imply resolution of unsampled transitions. The two panels use different phase subsets and geometry settings.')
    old.supplementary('S17','Common-mask full-waveform sensitivity of the 24/24 P1 gap test. Differences are centred on the same 102 phases and refer to h=0.50 mm.',['h mm','Combined RMS µm','Wave change RMS µm','Isolated change RMS µm','Fit residual µm'],[[r['h_mm'],f"{r['combined_rms_um']:.6f}",f"{r.get('combined_change_from_coarsest_rms_um',0):.6f}",f"{r.get('isolated_change_from_coarsest_rms_um',0):.6f}",f"{r['residual_rms_um']:.6f}"] for r in wr],[1.5,3.4,3.9,4.1,3.5])
    old.supplementary('S18','Cyclic erosion of the phase mask. Full-cycle results are analytical only. Each FE inversion uses eight starts per model. Singular values are scaled, whitened at σ=0.1 µm and normalized to 120 observations. Small signed objective differences are optimization roundoff.',['Mask','N','Rank at truth','Normalized s_min','Fit RMS µm','Null Δχ²'],[[r['mask'].replace('interior_guard_','Guard ').replace('full_analytical_only','Analytical full cycle'),r['n'],r['rank'],f"{r['budget_normalized_smin']:.4f}",f"{r['best']['fit_rmse_um']:.5f}" if 'best' in r else 'Not FE data',f"{r['delta_chi2_no_dedendum']:.3g}" if 'best' in r else 'Not FE data'] for r in m],[4.1,1,2.3,3.1,3.3,2.6])
    old.supplementary('S19','Pressure-hat interface sensitivity on 24 common eligible phases with identical P2 body meshes, fixed geometric trace and h=0.35 mm. Changes compare adjacent spacings. This subset is distinct from the 102-phase P1 inversion.',['Step mm','Isolated RMS µm','Signal change %','Combined wave change µm'],[[r['step_mm'],f"{r['isolated_dedendum_rms_um']:.6f}",f"{r.get('isolated_signal_relative_change_percent',0):+.4f}",f"{r.get('combined_waveform_change_rms_um',0):.6f}"] for r in ir],[2.4,4.6,4.6,4.8])
    old.supplementary('S20','Physically removed relief with reassembled stiffness and zero added gap. P2 elasticity; eight common eligible phases; upper pinion flanks and root blends; start 0.25; no addendum relief. Centred differences refer to nominal geometry on the same mesh. Removed area includes all modified pinion teeth. No full-cycle or inverse validation is asserted.',['h mm','Depth µm','Centred RMS µm','Mean approach change µm','Max relative H change','Area removed mm²'],[[r['h_mm'],r['depth_mm']*1000,f"{r['centered_TE_difference_rms_um']:.6f}",f"{r['mean_approach_change_um']:.6f}",f"{r['max_H_relative_change']:.5g}",f"{r['removed_area_mm2']:.5f}"] for r in pr],[1.4,1.8,3.2,3.9,3.5,2.6])
